/* Sampled 3D scatter projection: no interpolation implies unmeasured fitness. */
let landscapePoints=[],landLatest=[],landBest=null,landSeen=0,landGen=0,landConfig=null,landSampleState=12345,landScreen=[],landSelected=null,landRAF=false,landYaw=-.65,landPitch=.55,landZoom=1;
const landEl=id=>document.getElementById(id);
function resetLandscape(c){landscapePoints=[];landLatest=[];landBest=null;landSeen=0;landGen=0;landSelected=null;landConfig=c;landSampleState=12345;landEl('landTooltip').textContent='Waiting for evaluated layouts…';drawLandscape()}
function addLandscapePoint(m){if(!m.topology)return;const p={generation:m.generation,candidate:m.candidate,score:m.score,...m.topology,cached:m.cached};landSeen++;if(p.generation!==landGen){landGen=p.generation;landLatest=[]}landLatest.push(p);if(!landBest||p.score<landBest.score)landBest=p;if(landscapePoints.length<1600)landscapePoints.push(p);else{landSampleState=(Math.imul(landSampleState,1664525)+1013904223)>>>0;let i=Math.floor(landSampleState/4294967296*landSeen);if(i<1600)landscapePoints[i]=p}if(!landRAF){landRAF=true;requestAnimationFrame(()=>{landRAF=false;drawLandscape()})}}
function finishLandscape(m){if(m.topology)landBest={generation:landBest?.generation||m.config.generations,candidate:landBest?.candidate||1,score:m.score,...m.topology,winner:true};drawLandscape()}
function describeLand(p){let limit=Number(landEl('shortLimit').value);return `${p.runName?p.runName+' · ':''}Generation ${p.generation} · candidate ${p.candidate} · ${p.score} collisions · mean path ${p.meanPath.toFixed(2)} tile lengths · ${p.shortCounts[limit-1]} short exits / ${p.routeCount} boundary routes${p.winner?' · winner':p.cached?' · reused layout':''}`}
function drawLandscape(){const cv=landEl('landscapeCanvas');if(!cv||!landConfig)return;let width=cv.getBoundingClientRect().width;if(width<10)return;let height=cv.getBoundingClientRect().height||370,d=devicePixelRatio||1;cv.width=Math.round(width*d);cv.height=Math.round(height*d);let ctx=cv.getContext('2d');ctx.setTransform(d,0,0,d,0,0);ctx.fillStyle='#101914';ctx.fillRect(0,0,width,height);let limit=Number(landEl('shortLimit').value),view=landEl('landView').value,display=landEl('landDisplay').value||'points',showPoints=display!=='lines',showFits=display!=='points',latest=showFits?false:landEl('landGeneration').value==='latest';landEl('landGeneration').disabled=showFits;let groups=typeof landscapeRunGroups==='function'?landscapeRunGroups(latest):[{id:'current',name:'Current',color:'#9ddbc3',points:(latest?landLatest:landscapePoints).slice(),best:landBest,config:landConfig,seen:landSeen}];let data=groups.flatMap(g=>g.points.map(p=>({...p,runId:g.id,runName:g.name,runColor:g.color,winner:!!g.best&&p.generation===g.best.generation&&p.candidate===g.best.candidate})));for(let g of groups)if(g.best&&!latest&&!g.points.some(p=>p.generation===g.best.generation&&p.candidate===g.best.candidate))data.push({...g.best,runId:g.id,runName:g.name,runColor:g.color,winner:true});let maxPath=Math.max(1,...data.map(p=>p.meanPath))*1.06,maxShort=Math.max(1,...data.map(p=>p.shortCounts[limit-1])),maxScore=Math.max(1,...data.map(p=>p.score)),scale=Math.min(width*.58,height*.50)*landZoom;
const project=(x,y,z)=>{if(view==='path')return{x:45+x*(width-85),y:height-45-z*(height-85),depth:0};if(view==='short')return{x:45+y*(width-85),y:height-45-z*(height-85),depth:0};if(view==='top')return{x:45+x*(width-85),y:height-45-y*(height-85),depth:0};let a=x-.5,b=y-.5,rx=a*Math.cos(landYaw)-b*Math.sin(landYaw),dep=a*Math.sin(landYaw)+b*Math.cos(landYaw);return{x:width*.5+rx*scale,y:height*.68+(dep*Math.sin(landPitch)-z*Math.cos(landPitch))*scale,depth:dep*Math.cos(landPitch)+z*Math.sin(landPitch)}};
function line(a,b,color='#344638',weight=1){let p=project(...a),q=project(...b);ctx.strokeStyle=color;ctx.lineWidth=weight;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke()}
ctx.font='10px system-ui';ctx.textAlign='center';function textAt(text,x,y,z,color='#a2b09f',offset=0){let p=project(x,y,z);ctx.fillStyle=color;ctx.fillText(text,Math.max(35,Math.min(width-45,p.x)),Math.max(14,Math.min(height-12,p.y+offset)))}
if(view==='orbit'){for(let i=0;i<=4;i++){line([i/4,0,0],[i/4,1,0]);line([0,i/4,0],[1,i/4,0]);line([0,1,i/4],[1,1,i/4],'#28392f')}line([0,0,0],[1,0,0],'#94bca4',1.5);line([0,0,0],[0,1,0],'#94bca4',1.5);line([0,0,0],[0,0,1],'#eab17f',1.5);for(let i=0;i<=2;i++){textAt((maxPath*i/2).toFixed(1),i/2,0,0,'#9db8a7',16);textAt(String(Math.round(maxShort*i/2)),0,i/2,0,'#9db8a7',-6);textAt(String(Math.round(maxScore*i/2)),0,0,i/2,'#eab17f',-3)}textAt('Mean path length',.95,0,0,'#d5dfce',34);textAt('Short exit routes',0,.95,0,'#d5dfce',16);textAt('Collisions ↓ fitter',0,0,1,'#efc399',-20)}else{let xName=view==='short'?'Short exit routes':'Mean path length',yName=view==='top'?'Short exit routes':'Collisions',xMax=view==='short'?maxShort:maxPath,yMax=view==='top'?maxShort:maxScore;for(let i=0;i<=4;i++){let x=i/4,lineA=view==='short'?[0,x,0]:[x,0,0],lineB=view==='short'?[0,x,1]:view==='top'?[x,1,0]:[x,0,1];line(lineA,lineB);let y=i/4;if(view==='top')line([0,y,0],[1,y,0]);else if(view==='short')line([0,0,y],[0,1,y]);else line([0,0,y],[1,0,y]);ctx.fillStyle='#a2b09f';ctx.fillText((xMax*i/4).toFixed(view==='short'?0:1),45+x*(width-85),height-28);ctx.fillText((yMax*i/4).toFixed(0),23,height-45-y*(height-85))}ctx.fillText(xName,width/2,height-9);ctx.fillText(yName,88,16)}
let fits=[];if(showFits&&typeof anchoredFit==='function')for(let g of groups){if(!g.best||!g.stats)continue;let fit=anchoredFit(g.stats[limit-1],[g.best.meanPath,g.best.shortCounts[limit-1],g.best.score],[maxPath,maxShort,maxScore],g.points.map(p=>[p.meanPath,p.shortCounts[limit-1],p.score]));if(fit){fits.push({group:g,fit});line(fit.from,fit.to,g.color,3);let center=project(...fit.from);ctx.fillStyle=g.color;ctx.font='10px system-ui';ctx.fillText(g.name.slice(0,32),Math.max(10,Math.min(width-120,center.x+5)),Math.max(14,center.y-8))}}
landScreen=data.filter(p=>showPoints||p.winner).map(p=>({...project(p.meanPath/maxPath,p.shortCounts[limit-1]/maxShort,p.score/maxScore),point:p})).sort((a,b)=>a.depth-b.depth);for(let a of landScreen){let p=a.point,t=landConfig.generations<=1?0:(p.generation-1)/(landConfig.generations-1),isBest=!!p.winner;ctx.fillStyle=groups.length>1||showFits?p.runColor:`rgba(${Math.round(138+93*t)},${Math.round(183+5*t)},${Math.round(213-90*t)},.7)`;ctx.beginPath();ctx.arc(a.x,a.y,isBest?4:2.7,0,Math.PI*2);ctx.fill();if(isBest||landSelected&&p.generation===landSelected.generation&&p.candidate===landSelected.candidate&&p.runId===landSelected.runId){ctx.strokeStyle=isBest?'#d8ec9d':'#ffffff';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(a.x,a.y,6,0,Math.PI*2);ctx.stroke()}}
let legend=landEl('landRunLegend');legend.replaceChildren();for(let g of groups){let entry=document.createElement('span');entry.style.color=g.color;let fit=fits.find(f=>f.group.id===g.id)?.fit;entry.textContent=g.name+' · best '+(g.best?.score??'—')+(fit?' · line captures '+(fit.spread*100).toFixed(0)+'% of anchored spread':'');legend.append(entry)}
ctx.textAlign='left';landEl('landSummary').textContent=`${groups.length} run${groups.length===1?'':'s'} · ${groups.reduce((n,g)=>n+g.seen,0).toLocaleString()} observations · ${showFits?fits.length+' fitted lines':'sampled point clouds'}${latest?' · latest generation':''}. Lower collision height is fitter.`;landEl('shortLimitVal').textContent=limit;if(landSelected)landEl('landTooltip').textContent=describeLand(landSelected);if(!data.length){ctx.fillStyle='#a2b09f';ctx.fillText('The landscape appears as trials complete.',45,height/2)}}
let landDrag=null;
landEl('landscapeCanvas').onpointerdown=e=>{landDrag={x:e.clientX,y:e.clientY,moved:0};e.currentTarget.setPointerCapture?.(e.pointerId)};
landEl('landscapeCanvas').onpointermove=e=>{if(!landDrag)return;let dx=e.clientX-landDrag.x,dy=e.clientY-landDrag.y;landDrag.moved+=Math.abs(dx)+Math.abs(dy);landDrag.x=e.clientX;landDrag.y=e.clientY;if(landEl('landView').value==='orbit'){landYaw+=dx*.008;landPitch=Math.max(.1,Math.min(1.35,landPitch+dy*.008));drawLandscape()}};
landEl('landscapeCanvas').onpointerup=e=>{if(landDrag&&landDrag.moved<6){let r=e.currentTarget.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,best=null,dist=100;for(let p of landScreen){let dd=(x-p.x)**2+(y-p.y)**2;if(dd<dist){best=p.point;dist=dd}}if(best){landSelected=best;landEl('landTooltip').textContent=describeLand(best);drawLandscape()}}landDrag=null};
landEl('landscapeCanvas').onpointercancel=()=>landDrag=null;
landEl('landscapeCanvas').onwheel=e=>{e.preventDefault();landZoom=Math.max(.5,Math.min(1.8,landZoom*Math.exp(-e.deltaY*.001)));drawLandscape()};
landEl('landscapeCanvas').onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();if(e.key==='ArrowLeft')landYaw-=.1;if(e.key==='ArrowRight')landYaw+=.1;if(e.key==='ArrowUp')landPitch=Math.min(1.35,landPitch+.1);if(e.key==='ArrowDown')landPitch=Math.max(.1,landPitch-.1);drawLandscape()};
for(let id of ['shortLimit','landGeneration','landView']){landEl(id).oninput=drawLandscape;landEl(id).onchange=drawLandscape}
landEl('landReset').onclick=()=>{landYaw=-.65;landPitch=.55;landZoom=1;drawLandscape()};

new ResizeObserver(drawLandscape).observe(landEl('landscapeCanvas'));
